"""Publish the selected green-fan revision and retain its comparison page."""
from pathlib import Path
import json,sys,hashlib,shutil,math
ROOT=Path(__file__).resolve().parents[3]
B=Path(sys.argv[1]);D=ROOT/'docs/gallery/key-fan/stacked/green';R=ROOT/'bench/reviews/green-fan-v1'
D.mkdir(parents=True,exist_ok=True);R.mkdir(parents=True,exist_ok=True)
layout=json.loads((B/'layout.json').read_text());access=json.loads((B/'access.json').read_text());native=json.loads((B/'tight-native/native.json').read_text());sweep=json.loads((B/'tight-native/sweep-check.json').read_text())
pinch=json.loads((B/'tight-native/pinch-check.json').read_text())
print_check=json.loads((B/'tight-native/print-check.json').read_text())
assert print_check['passed']
slice_review=json.loads((B/'previous-filled-slice-receipt.json').read_text())
toolpaths=json.loads((B/'previous-filled-toolpaths.json').read_text())
assert pinch['passed'] and len(pinch['rows'])==10
assert access['passed'] and sweep['passed'] and len(sweep['rows'])==26
rack=next(r for r in native['racks'] if r['id']=='HX05C')
assert rack['valid'] and rack['solids']==1 and rack['stored_overlap_mm3']<1e-5
assert all(c['overlap_mm3']<1e-5 for c in rack['cavity_gaps'])
for name in ('layout.json','access.json','spacing.json','previous-filled-slice-receipt.json','previous-filled-toolpaths.json','previous-filled-slice-input.json'):shutil.copyfile(B/name,R/name)
for name in ('native.json','sweep-check.json','pinch-check.json','print-check.json'):shutil.copyfile(B/'tight-native'/name,R/name)
for name in ('HX05C-hero.jpg','HX05C-front.jpg','HX05C-plan.jpg','HX05C-empty-hero.jpg','HX05C-print-hero.jpg','stack-hero.jpg'):shutil.copyfile(B/'renders'/name,D/name)
b=rack['bounds'];w,d,h=[b[i+1]-b[i] for i in (0,2,4)]
rows=''.join(f"<tr><th>{t['name']}</th><td>{t['guide']/1.5:.1f}</td><td>{t['guide']:.1f}</td><td>{math.degrees(math.asin(t['axis'][2])):.1f}°</td></tr>" for t in sorted(rack['tools'],key=lambda t:t['af']))
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Green fan · gravity seating and broad fin roots</title><style>body{{margin:0;background:#f5f3ec;color:#222;font:18px/1.55 system-ui,sans-serif}}main{{max-width:1000px;margin:auto;padding:24px}}a,summary{{color:#126657}}h1,h2{{line-height:1.15}}img{{display:block;width:100%;height:auto;border-radius:14px;background:#ece9df;margin:18px 0}}section{{margin:38px 0}}table{{width:100%;border-collapse:collapse;font-size:16px}}th,td{{text-align:left;padding:10px;border-bottom:1px solid #ccc}}summary{{cursor:pointer}}.note{{border-left:5px solid #247b6d;padding:16px;background:#e0eee7}}.stack{{max-width:540px;margin:auto}}</style></head><body><main><nav><a href="../">Previous three-stack review</a> · <a href="../../final/">Earlier final models</a></nav><h1>Green fan: gravity seating and broad fin roots</h1><p class="note">The selected Bondhus 13190 inch fan, with <strong>50% longer straight sleeves</strong> and T-bars twisted <strong>30° toward the pegboard plane</strong>. Every key points at least <strong>10° upward</strong> from its seated tip toward its handle. The lowest green key is set to <strong>10.5°</strong>. Enlarged tapered fin roots brace the sleeves in the print-bed plane.</p><img src="HX05C-hero.jpg" width="1200" height="850" alt="Green inch fan with longer sleeves and handles turned toward the pegboard plane"><p>Gravity draws each key toward its blind floor. The shafts fan across the board and splay 11.5–21.1° out of its plane, preserving the tucked tips and pinch access. The 3/8-inch shaft rises from 9.69° to 10.5°, with its handle and hex clocking rotated together. The other key angles already exceed 10°. The T-bars retain their flatter orientation toward the board.</p><details><summary>Front and plan views</summary><img loading="lazy" src="HX05C-front.jpg" width="1200" height="700" alt="Front view of the flatter T-bars"><img loading="lazy" src="HX05C-plan.jpg" width="1200" height="600" alt="Plan view showing the T-bars turned toward the board"></details><section><h2>Longer straight engagement</h2><img loading="lazy" src="HX05C-empty-hero.jpg" width="1200" height="850" alt="Empty native green holder showing its longer sleeves"><p>Straight engagement increases from 40–76.2 mm to 60–114.3 mm. Each entrance retains the 3 mm axial lead-in opening 1.5 mm per flat, +0.38 mm total AF clearance, square stop and 1 mm vent. The C fit was physically selected only on the owner's 3 mm / 5 mm coupons; these inch sizes and longer guides need physical confirmation.</p><table><caption>Straight guide length, mm; the 3 mm lead-in is additional</caption><thead><tr><th>Key</th><th>Previous</th><th>New</th><th>Upward tilt</th></tr></thead><tbody>{rows}</tbody></table></section><section><h2>Filled bending planes and tip-face print pose</h2><p>A solid wedge joins the sleeves to the backplate and tip-end base. Each fin now has a tapered root widened <strong>12 mm per side</strong> in print XY (installed YZ), extending <strong>16 mm toward the print bed</strong>. The broad roots merge into the backplate and filled base. Full lead-in openings are reserved through the extra material. The base retains 8 mm corner rounds, and the fin roots use broad tapered connections to the backplate. CAD solid volume is {rack['volume']/1e6:.3f} litres; actual filament depends on the slice.</p><img loading="lazy" src="HX05C-print-hero.jpg" width="1200" height="850" alt="Filled rack resting on its broad left tip face, diagonally on a 256 mm print bed"><p>The flat tip face provides {print_check['bed_contact_area_cm2']:.1f} cm² of native bed contact. At 45° on the bed, the nominal print envelope is {' × '.join(f"{x:.1f}" for x in print_check['print_dimensions_mm'])} mm. Vents remain 1 mm, routed forward perpendicular to each shaft through the added stock. Native probes confirm every vent and entrance is open; the board-side peg geometry is unchanged.</p><p class="note"><strong>This revision has not been sliced.</strong> The preceding filled-base revision estimated 57 h 32 min and 991 g ASA in the owner’s P1S/Orca profile. Its support screen found 35 moves inside the 9/64-inch socket. Those figures belong to the previous geometry. A new slice with socket support blockers and a support/contact review is required before printing.</p></section><section><h2>Size and stack</h2><p>The native holder is <strong>{w:.1f} × {d:.1f} × {h:.1f} mm</strong> (width × depth × height, including rear pegs and excluding tools). The selected previous green holder was 184.0 × 91.3 × 239.2 mm.</p><p>Only the green inch rack changes. The blue metric and orange Torx holders retain their geometry. The revised stack uses 254.0 mm (10 rows) from inch to metric, then 228.6 mm (9 rows) to Torx.</p><img class="stack" loading="lazy" src="stack-hero.jpg" width="800" height="1300" alt="Revised green inch fan below the unchanged blue metric and orange Torx fans"></section><section><h2>Checks and limits</h2><p>All 26 stored-tool and axial socket-release checks pass for this stack. The green rack is checked for a two-finger pinch at the front end of each handle: two assumed 24 × 18 × 10 mm fingertip pads, spanning 38 mm across the 18 mm grip. All ten pinch approaches and axial-release sweeps clear the neighboring tools and native holders. Native bodies are valid single solids; stored tool/body overlap is zero. The green socket cavities remain separate.</p><p>Tools are catalogue envelopes with an assumed 18 mm grip diameter. Subsequent free-hand removal, whole-rack installation, physical printing, support removal and loads remain unqualified. The previous Orca archive also emitted placeable-area diagnostics during organic-support generation; it is retained as historical evidence only. These are review renders, not qualified print files.</p><p><a href="review.json">Numerical review</a> · <a href="https://github.com/thereprocase/peg/tree/main/bench/source/green_fan_v1">Construction source</a></p></section></main></body></html>'''
(D/'index.html').write_text(page,encoding='utf-8')
source_paths=list((ROOT/'bench/source/green_fan_v1').glob('*'))+list((ROOT/'bench/source/stacked_fans_v1').glob('*.py'))
source_hashes={str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(source_paths) if p.is_file()}
review=dict(layout_sha256=hashlib.sha256((B/'layout.json').read_bytes()).hexdigest(),holder_dimensions_mm=[w,d,h],guide_multiplier=1.5,bar_twist_toward_board_degrees=30,tool_hand_access_passed=access['passed'],native_sweeps=sweep,pinch_checks=pinch,print_checks=print_check,previous_filled_revision=dict(commit='a3e68b31db81ac380ac73f2e9bb1b64a3b9e64bb',slice_review=slice_review,toolpath_screen=toolpaths),current_slice_status='Not sliced; previous geometry slice does not transfer',green_native=rack,source_hashes=source_hashes)
(D/'review.json').write_text(json.dumps(review,indent=2)+'\n')
parent=D.parent/'index.html';s=parent.read_text();link='<a href="green/">Green fan: longer sleeves + flatter handles</a> · '
if link not in s:s=s.replace('<nav>','<nav>'+link)
parent.write_text(s)
# Refresh the older review's changed navigation receipt, preserving its CAD.
p=ROOT/'publication/stacked-fans-v1-review.json';old=json.loads(p.read_text());old[str(parent.relative_to(ROOT))]=dict(bytes=parent.stat().st_size,sha256=hashlib.sha256(parent.read_bytes()).hexdigest());p.write_text(json.dumps(old,indent=2)+'\n')
receipts={}
for base in (D,R,ROOT/'bench/source/green_fan_v1'):
 for p in sorted(base.rglob('*')):
  if p.is_file() and '__pycache__' not in p.parts:receipts[str(p.relative_to(ROOT))]=dict(bytes=p.stat().st_size,sha256=hashlib.sha256(p.read_bytes()).hexdigest())
(ROOT/'publication/green-fan-v1-review.json').write_text(json.dumps(receipts,indent=2)+'\n')
print('Published local green review',len(receipts),'files;',sum(p.stat().st_size for p in D.iterdir()),'site bytes')
import runpy
runpy.run_path(str(ROOT/'bench/source/hx05_parametric_v1/publish_download.py'))['install'](ROOT)
